<?php
require_once __DIR__ . '/../includes/layout.php'; require_admin();
if ($_SERVER['REQUEST_METHOD'] === 'POST') { execute('UPDATE fines SET status=?,notes=? WHERE id=?', [$_POST['status'], trim($_POST['notes'] ?? ''), (int) $_POST['id']]); flash('Status denda diperbarui.'); redirect('admin/fines.php'); }
$memberId = trim($_GET['member_id'] ?? ''); $bookId = trim($_GET['book_id'] ?? '');
$sql = 'SELECT f.*,u.name,u.member_id,b.title,b.book_id FROM fines f JOIN users u ON u.id=f.user_id LEFT JOIN borrowings br ON br.id=f.borrowing_id LEFT JOIN books b ON b.id=br.book_id WHERE u.member_id LIKE ? AND COALESCE(b.book_id,"") LIKE ? ORDER BY f.created_at DESC';
$data = rows($sql, ['%' . $memberId . '%', '%' . $bookId . '%']);
page_head('Denda', true); admin_heading('Denda & Sanksi', 'Kelola denda keterlambatan dan kehilangan');
?>
<form class="toolbar admin-id-search" method="get"><input name="member_id" value="<?= e($memberId) ?>" placeholder="Cari ID anggota"><input name="book_id" value="<?= e($bookId) ?>" placeholder="Cari ID buku"><button type="submit">Cari</button><a class="button secondary" href="<?= e(url('admin/fines.php')) ?>">Reset</a></form>
<section class="card table-card"><table><thead><tr><th>Anggota</th><th>Buku</th><th>Jenis</th><th>Hari</th><th>Jumlah</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($data as $row): ?><tr><td><?= e($row['name']) ?><br><small class="muted"><?= e($row['member_id']) ?></small></td><td><?= e($row['title'] ?? '-') ?><br><small class="muted"><?= e($row['book_id'] ?? '-') ?></small></td><td><?= e($row['type']) ?></td><td><?= e($row['days_late']) ?></td><td><?= rupiah((int) $row['amount']) ?></td><td><?= status_badge($row['status']) ?></td><td><?php if ($row['status'] === 'unpaid'): ?><form method="post" class="actions"><input type="hidden" name="id" value="<?= (int) $row['id'] ?>"><input type="hidden" name="status" value="paid"><input type="hidden" name="notes" value="Dibayar melalui kasir"><button class="success">Tandai lunas</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$data): ?><tr><td colspan="7" class="muted">Tidak ada data denda.</td></tr><?php endif; ?></tbody></table></section>
<?php page_foot(true); ?>
